using System;using System.IO;using System.Reflection;using System.Collections.Generic;using Expedition.Core;
class TimingReview {
static CatalogDatabase db;static int n,f;static object C(CatalogBattle b,string m,params object[] x){foreach(MethodInfo method in typeof(CatalogBattle).GetMethods(BindingFlags.Instance|BindingFlags.NonPublic))if(method.Name==m&&method.GetParameters().Length==x.Length)return method.Invoke(b,x);throw new MissingMethodException("No matching review call: "+m+"/"+x.Length);}static void Check(bool ok,string s){n++;if(!ok)f++;Console.WriteLine((ok?"PASS ":"FAIL ")+s);}static void Run(CatalogBattle b,float sec){for(int i=0;i<Math.Round(sec*60);i++)b.Step(1f/60f);}static CatalogBattleUnit A(CatalogBattle b,string id,string form,string trait=null){var a=b.AddUnit(id,CatalogTeam.Ally,form,null,trait,0,0);a.NextBasicAt=a.NextPrimaryAt=10000;return a;}static CatalogBattleUnit E(CatalogBattle b,string id,float x=1){var e=b.AddEnemy(id,10000,1,0,100,1,1,false,x,0);e.NextBasicAt=10000;return e;}
static int Main(string[] args){db=CatalogDatabase.FromJson(File.ReadAllText(args[0]));CatalogBattle b;CatalogBattleUnit a,e,z;
b=new CatalogBattle(db);a=A(b,"a","B-FI");a.Power=100;e=E(b,"e");var low=A(b,"low","B-FI");low.Power=50;C(b,"Burn",a,e);Run(b,.5f);C(b,"Burn",low,e);Check(e.BurnSourceId=="a"&&Math.Abs(e.BurnDamage-15)<.001f&&Math.Abs(e.BurnUntil-3)<.001f,"Weaker burn does not overwrite source, damage, or expiry");int ticks=0;b.Event+=ev=>{if(ev.Kind==CatalogEventKind.Damage&&ev.AbilityId=="BURN")ticks++;};Run(b,2.6f);Check(ticks==3&&Math.Abs(e.Hp-9955)<.01,"Single burn applies exactly three ticks by 3 seconds");
b=new CatalogBattle(db);a=A(b,"a","B-FI");a.Power=100;e=E(b,"e");ticks=0;b.Event+=ev=>{if(ev.Kind==CatalogEventKind.Damage&&ev.AbilityId=="BURN")ticks++;};for(int i=0;i<180;i++){C(b,"Burn",a,e);b.Step(1f/60f);}Check(ticks>=2,"Every-frame burn refresh cannot starve periodic damage");
b=new CatalogBattle(db);a=A(b,"a","E-FI-E");a.Power=100;e=E(b,"old");z=E(b,"new",5);int oldTicks=0,newTicks=0;b.Event+=ev=>{if(ev.Kind==CatalogEventKind.Damage&&ev.AbilityId=="E-FI-E"){if(ev.TargetId=="old")oldTicks++;if(ev.TargetId=="new")newTicks++;}};C(b,"ExecuteSkill",a,e,"E-FI-E");e.X=5;z.X=1;Run(b,1.1f);Check(oldTicks==0&&newTicks==1,"Zone re-evaluates occupants at tick, not at cast");a.Hp=0;Run(b,3);Check(newTicks==1,"Caster death stops remaining zone ticks");
b=new CatalogBattle(db);a=A(b,"a","H-06","T-FI");a.Power=100;e=E(b,"e");e.Hp=10;z=A(b,"friend","B-KN");z.Hp=1;C(b,"Burn",a,e);string killer=null;b.Event+=ev=>{if(ev.Kind==CatalogEventKind.Defeated)killer=ev.SourceId;};Run(b,1.1f);Check(killer=="a"&&z.Hp>1,"Burn kill credits original caster and triggers living caster Spoils");
b=new CatalogBattle(db);a=A(b,"a","H-06","T-FI");a.Power=100;e=E(b,"e");e.Hp=10;z=A(b,"friend","B-KN");z.Hp=1;C(b,"Burn",a,e);a.Hp=0;Run(b,1.1f);Check(z.Hp==1,"Dead burn caster cannot trigger Spoils");
// All twelve final branch selections must actually execute retained branch, not merely store its ID.
foreach(string branch in new[]{"E-KN-G","E-KN-C","E-AR-P","E-AR-T","E-FI-B","E-FI-E","E-PR-G","E-PR-H","E-IC-F","E-IC-S","E-BA-G","E-BA-A"}){
b=new CatalogBattle(db);string form="F-"+branch.Substring(2,2);a=b.AddUnit("a",CatalogTeam.Ally,form,branch,null,0,0);a.MaxHp=10000;a.Hp=8000;e=E(b,"e");e.Hp=e.MaxHp=100000;z=A(b,"friend","B-KN");z.Hp=1;var used=new HashSet<string>();b.Event+=ev=>{if(ev.Kind==CatalogEventKind.SkillUsed&&ev.SourceId=="a")used.Add(ev.AbilityId);};if(branch=="E-KN-C"){C(b,"GiveShield",a,a,10f,4f,"TEST");C(b,"Damage",e,a,100f,"BASIC",true,false);}Run(b,14);Check(used.Contains(form)&&used.Contains(branch),"Final and retained branch both execute: "+branch);
}
Console.WriteLine("TIMING REVIEW "+n+" checks; "+f+" failures");return f==0?0:1;}}
